import { describe, expect, it } from "vitest";
import { normalizePhone } from "./phone";

describe("normalizePhone", () => {
  it("strips formatting", () => {
    for (const v of ["+7 701 555 12 34", "+7 (701) 555-12-34", "+7-701-555-12-34", "+7.701.555.12.34", "+77015551234"]) {
      expect(normalizePhone(v)).toBe("+77015551234");
